import { readFileSync } from 'fs';
import { resolve } from 'path';

import { crc16, Fragmenter, MAX_FRAME_BYTES, Reassembler, StoreAndForward, StreamFramer, VirtualLink, makeFrame } from '../index.js';

interface FragVector {
  name: string;
  mtu: number;
  msgId: number;
  frameHex: string;
  packetsHex: string[];
}

interface Vectors {
  schema: string;
  crc16: Array<{ hex: string; value: number }>;
  fragmentation: FragVector[];
  stream: Array<{ name: string; frameHex: string }>;
}

// Conformance corpus generated by the C++ reference implementation
// (hawk-node: ble_gen_vectors). Both languages must pass the same file.
const vectors: Vectors = JSON.parse(
  readFileSync(resolve(__dirname, '../../../../../packages/edge-mesh/test-vectors/mesh-v1.json'), 'utf8'),
);

const hex = (data: Uint8Array): string =>
  Array.from(data, (b) => b.toString(16).padStart(2, '0')).join('');

const unhex = (text: string): Uint8Array => {
  const out = new Uint8Array(text.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(text.slice(i * 2, i * 2 + 2), 16);
  return out;
};

const bytes = (n: number, seed = 0): Uint8Array => {
  const out = new Uint8Array(n);
  for (let i = 0; i < n; i++) out[i] = (seed + i * 31) & 0xff;
  return out;
};

describe('edge-mesh conformance (shared with hawk-node)', () => {
  test('the corpus is the expected schema', () => {
    expect(vectors.schema).toBe('totem-edge-mesh/1');
    expect(vectors.fragmentation.length).toBeGreaterThan(0);
  });

  test.each(vectors.crc16)('crc16 matches the C++ value for $hex', ({ hex: input, value }) => {
    expect(crc16(unhex(input))).toBe(value);
  });

  test.each(vectors.fragmentation)('$name fragments identically', (vector) => {
    const fragmenter = new Fragmenter(vector.mtu);
    const packets = fragmenter.fragment(vector.msgId, unhex(vector.frameHex));
    expect(packets.map(hex)).toEqual(vector.packetsHex);
  });

  test.each(vectors.fragmentation)('$name reassembles in order', (vector) => {
    const reassembler = new Reassembler();
    let frame: Uint8Array | undefined;
    for (const packet of vector.packetsHex.map(unhex)) {
      frame = reassembler.add(packet, 1000) ?? frame;
    }
    expect(frame && hex(frame)).toBe(vector.frameHex);
    expect(reassembler.pending).toBe(0);
  });

  test.each(vectors.fragmentation)('$name reassembles out of order', (vector) => {
    const reassembler = new Reassembler();
    let frame: Uint8Array | undefined;
    const packets = vector.packetsHex.map(unhex).reverse();
    for (const packet of packets) {
      frame = reassembler.add(packet, 1000) ?? frame;
    }
    expect(frame && hex(frame)).toBe(vector.frameHex);
  });

  test.each(vectors.fragmentation)('$name tolerates a duplicate fragment', (vector) => {
    const packets = vector.packetsHex.map(unhex);
    if (packets.length < 2) return;
    const reassembler = new Reassembler();
    expect(reassembler.add(packets[0], 1000)).toBeUndefined();
    expect(reassembler.add(packets[0], 1000)).toBeUndefined();
    let frame: Uint8Array | undefined;
    for (const packet of packets.slice(1)) {
      frame = reassembler.add(packet, 1000) ?? frame;
    }
    expect(frame && hex(frame)).toBe(vector.frameHex);
  });

  test.each(vectors.fragmentation)('$name rejects a corrupt fragment', (vector) => {
    const packets = vector.packetsHex.map(unhex);
    if (packets.length < 2) return;
    const corrupted = packets[0].slice();
    corrupted[corrupted.length - 1] ^= 0xff;
    const reassembler = new Reassembler();
    expect(reassembler.add(corrupted, 1000)).toBeUndefined();
    expect(reassembler.add(packets[1], 1000)).toBeUndefined();
  });

  test.each(vectors.stream)('$name survives stream framing', (vector) => {
    const wire = unhex(vector.frameHex);
    const framer = new StreamFramer();
    framer.push(wire.subarray(0, 2));
    expect(framer.next()).toBeUndefined();
    framer.push(wire.subarray(2));
    const frame = framer.next();
    expect(frame && hex(frame)).toBe(vector.frameHex);
    expect(framer.next()).toBeUndefined();
  });
});

describe('edge-mesh behaviour', () => {
  test('an MTU below the header is rejected', () => {
    expect(() => new Fragmenter(13)).toThrow();
  });

  test('an oversized frame is rejected', () => {
    expect(() => new Fragmenter(185).fragment(1, new Uint8Array(MAX_FRAME_BYTES + 1))).toThrow();
  });

  test('a one-block IBD frame fits in two packets at MTU 185', () => {
    const fragmenter = new Fragmenter(185);
    expect(fragmenter.payloadPerPacket).toBe(172);
    expect(fragmenter.fragment(42, bytes(314, 7))).toHaveLength(2);
  });

  test('the reassembler expires half-built frames', () => {
    const fragmenter = new Fragmenter(185);
    const packets = fragmenter.fragment(5, bytes(314, 7));
    const reassembler = new Reassembler();
    expect(reassembler.add(packets[0], 1000)).toBeUndefined();
    reassembler.expire(1200, 300);
    expect(reassembler.pending).toBe(1);
    reassembler.expire(1301, 300);
    expect(reassembler.pending).toBe(0);
  });

  test('the relay queue dedupes, bounds bytes and expires', () => {
    const queue = new StoreAndForward(100, 7, 5000);
    const f1 = bytes(60, 1);
    const f2 = bytes(60, 2);
    expect(queue.add(f1, 1000)).toBe(true);
    expect(queue.add(f1, 1000)).toBe(false);
    expect(queue.add(f2, 1000)).toBe(true);
    expect(queue.count).toBe(1);
    const taken = queue.take(1000);
    expect(taken).toHaveLength(1);
    expect(hex(taken[0])).toBe(hex(f2));
    expect(queue.count).toBe(0);
    expect(queue.bytes).toBe(0);
    expect(queue.seen(f2, 1000)).toBe(true);
    expect(queue.seen(f2, 6001)).toBe(false);
    expect(queue.add(f2, 6001)).toBe(true);
  });

  test('the virtual link drops oversized and injected packets', () => {
    const link = new VirtualLink(185);
    link.send(bytes(100));
    expect(link.receive()).toBeDefined();
    link.send(bytes(200));
    expect(link.receive()).toBeUndefined();
    expect(link.droppedCount).toBe(1);
    link.dropNextPacket();
    link.send(bytes(10));
    expect(link.receive()).toBeUndefined();
  });

  test('makeFrame matches the node wire layout', () => {
    const wire = makeFrame(1, bytes(313, 3));
    expect(wire).toHaveLength(318);
    expect(wire[0]).toBe(0);
    expect(wire[1]).toBe(0);
    expect(wire[2]).toBe(0x01);
    expect(wire[3]).toBe(0x3a);
    expect(wire[4]).toBe(1);
  });

  test('an absurd stream length is rejected', () => {
    const framer = new StreamFramer();
    framer.push(new Uint8Array([0xff, 0xff, 0xff, 0xff]));
    expect(() => framer.next()).toThrow();
  });
});
